__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["filters"] = function(...)
-- =====================================================================
-- Lib: catalog filter helpers: unified KEY constants, schema builders
--      (select/checkbox/text/tristate), common OPTIONS, safe getter.
-- Schema per lua-plugin-guide.md «Фильтры каталога» (getFilterList).
-- Loaded via require_lib("filters"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- =====================================================================
-- Unified filter keys
-- =====================================================================

-- Keys as Kotlin delivers them into the `filters` table of
-- getCatalogFiltered (guide: checkbox/tristate/tag_input values arrive
-- under "<key>_included"/"<key>_excluded", selects/switches/text under
-- "<key>"). Genres are unified on "genre_included" — already the read
-- key in 28 plugins; declare checkbox filters with key = "genre".
M.KEY = {
    genre  = "genre_included",
    status = "status",
    type   = "type",
    sort   = "sort",
}

-- =====================================================================
-- Schema builders (getFilterList elements)
-- =====================================================================

-- Select one value: { type, key, label, defaultValue, options }.
function M.select(key, label, options, default)
    return { type = "select", key = key, label = label, defaultValue = default, options = options }
end

-- Multi-include checkbox: values arrive as filters[key .. "_included"]
-- (so a checkbox with key "genre" is read via M.KEY.genre).
function M.checkbox(key, label, options)
    return { type = "checkbox", key = key, label = label, options = options }
end

-- Free-text input; `default` maps to defaultValue ("" when omitted,
-- per the guide's author example).
function M.text(key, label, default)
    return { type = "text", key = key, label = label, defaultValue = default or "" }
end

-- Include/exclude/ignore per option: values arrive as
-- filters[key .. "_included"] / filters[key .. "_excluded"].
function M.tristate(key, label, options)
    return { type = "tristate", key = key, label = label, options = options }
end

-- =====================================================================
-- Common option sets
-- =====================================================================

-- Anime type / airing status — from en/hianimes.lua:386-401
-- (the only general-purpose pair found across plugins); sort — the
-- generic trio from the guide's select example. Sites with their own
-- vocabularies keep local option tables.
M.OPTIONS = {
    type = {
        { value = "All",     label = "All" },
        { value = "TV",      label = "TV" },
        { value = "Movie",   label = "Movie" },
        { value = "OVA",     label = "OVA" },
        { value = "Special", label = "Special" },
        { value = "ONA",     label = "ONA" },
        { value = "Music",   label = "Music" },
    },
    status = {
        { value = "All",       label = "All" },
        { value = "Airing",    label = "Airing" },
        { value = "Completed", label = "Completed" },
        { value = "Upcoming",  label = "Upcoming" },
    },
    sort = {
        { value = "latest",  label = "Latest Update" },
        { value = "popular", label = "Most Popular" },
        { value = "rating",  label = "Top Rated" },
    },
}

-- =====================================================================
-- Value access
-- =====================================================================

-- Safe getter for a filter value with default: tolerates nil/empty
-- `filters` (Kotlin may pass nothing when the user never opened the
-- filter sheet). Works for select strings and checkbox/tristate arrays.
function M.get(filters, key, default)
    if type(filters) ~= "table" then return default end
    local v = filters[key]
    if v == nil then return default end
    return v
end

return M
end

__LOADERS["text"] = function(...)
-- =====================================================================
-- Lib: text rotations (rot13, rot18).
-- No XOR here on purpose: the xor "duplicates" found in three plugins are
-- internals of hmac-sha256 / AES-GCM and disappear with the Kotlin APIs,
-- the only standalone str-xor (en/hianimes.lua) stays inline in the plugin.
-- Loaded via require_lib("text"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- ROT13 over Latin letters. Bodies of the three copies were equivalent:
-- libs/voe.lua:15, ar/anime4up.lua:383, en/novelhi.lua:33 (the guard for
-- nil/empty comes from novelhi).
function M.rot13(s)
    if not s or s == "" then return "" end
    return (s:gsub("[%a]", function(c)
        local b = c:byte()
        local base = (b < 97) and 65 or 97
        return string.char(base + ((b - base + 13) % 26))
    end))
end

-- Kodik rotation: +18 over letters only, digits untouched — this is NOT
-- the classic ROT13+ROT5 pair, digits must survive as-is or the base64
-- after decoding breaks (sole copy: ru/yummyanime.lua:511 kodikDecode).
function M.rot18(s)
    if not s or s == "" then return "" end
    local t = {}
    for i = 1, #s do
        local b = s:byte(i)
        if b >= 65 and b <= 90 then
            b = b + 18
            if b > 90 then b = b - 26 end
        elseif b >= 97 and b <= 122 then
            b = b + 18
            if b > 122 then b = b - 26 end
        end
        t[#t + 1] = string.char(b)
    end
    return table.concat(t)
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
-- END BUNDLED LIBRARIES (tools/bundle_libs.py)
-- AniLiberty — видео-плагин Dreamora (content_type = "video")
-- API: https://aniliberty.top/api/v1 (JSON), сайт: https://aniliberty.top
-- Референс: miru-project/repo/repo/aniliberty.js

content_type = "video"
id          = "aniliberty"
name        = "AniLiberty"
version     = "1.0.1"
baseUrl     = "https://aniliberty.top"
language = {"ru", "en"}
icon        = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/aniliberty.png"

local API = baseUrl .. "/api/v1"
-- Максимум, который принимает каталог (100 → HTTP 422)
local CATALOG_LIMIT = 50

-- Old builds ship no require_lib: keep the plugin loadable (a top-level
-- error would drop it from the source list) and fail with a visible
-- message on the first call instead. require_lib caches loaded libs.
local function lib(id)
    if type(require_lib) ~= "function" then
        show_error("Требуется обновление Dreamora", "Плагину нужны общие библиотеки")
        error("Требуется обновление Dreamora (require_lib)", 0)
    end
    return require_lib(id)
end

-- Сессионный кэш detail-ответов — fetch.page (кэш по URL живёт в либе)
local function fetchDetail(bookUrl)
    local alias = bookUrl:match("/release/([^/]+)/")
    if not alias then return nil end
    local body = lib("fetch").page(API .. "/anime/releases/" .. alias)
    if not body then return nil end
    local data = json_parse(body)
    if type(data) ~= "table" then return nil end
    return data
end

-- Название, усечённое сайтом (многоточие в конце ответа API).
local function isCutTitle(s)
    s = string_trim(s)
    return string_ends_with(s, "…") or string_ends_with(s, "...")
end

-- Полное название из объекта name. Часть записей в базе сайта хранится уже
-- усечённой («…» в конце), тогда полное название лежит в соседнем поле
-- name.english — проверено на ответах catalog/search/detail и на HTML
-- страницы релиза: fantasy-bishoujo-juniku-ojisan-to →
--   main:    "Фантастический мир с обращённым в красавицу мужчиной и…"
--   english: "Fantasy Bishoujo Juniku Ojisan to"
-- nil возвращает, только если названия нет вовсе.
local function pickTitle(name)
    if type(name) ~= "table" then return nil end
    local main, eng = name.main, name.english
    if type(main) == "string" and main ~= "" and not isCutTitle(main) then
        return main
    end
    if type(eng) == "string" and eng ~= "" and not isCutTitle(eng) then
        return eng
    end
    -- оба поля усечены или english отсутствует — отдаём как есть
    if type(main) == "string" and main ~= "" then return main end
    if type(eng) == "string" and eng ~= "" then return eng end
    return nil
end

local function itemToBook(item)
    if type(item) ~= "table" or not item.alias then return nil end
    local title = pickTitle(item.name)
    if not title then return nil end
    local cover = ""
    if item.poster and item.poster.src then cover = baseUrl .. item.poster.src end
    local book = {
        title = string_clean(title),
        url   = baseUrl .. "/anime/releases/release/" .. item.alias .. "/episodes",
        cover = cover,
    }
    local avg = item.rating and item.rating.average
    if type(avg) == "number" then
        book.rating = "Rating: " .. tostring(avg) .. "/10"
    end
    return book
end

local function itemsToResult(arr)
    local items = {}
    if type(arr) == "table" then
        for _, item in ipairs(arr) do
            local book = itemToBook(item)
            if book then table.insert(items, book) end
        end
    end
    return { items = items, hasNext = false }
end

-- Каталог: { data = { ... }, meta.pagination = { total, current_page, total_pages, ... } }
local function fetchCatalog(url)
    local r = http_get(url)
    if not r.success then return { items = {}, hasNext = false } end
    local body = json_parse(r.body)
    if type(body) ~= "table" or type(body.data) ~= "table" then
        return { items = {}, hasNext = false }
    end
    local items = {}
    for _, item in ipairs(body.data) do
        local book = itemToBook(item)
        if book then table.insert(items, book) end
    end
    local pag = body.meta and body.meta.pagination
    local hasNext = false
    if type(pag) == "table" then
        hasNext = (tonumber(pag.current_page) or 0) < (tonumber(pag.total_pages) or 0)
    end
    return { items = items, hasNext = hasNext }
end

local function catalogUrl(page, query)
    local url = API .. "/anime/catalog/releases?page=" .. page .. "&limit=" .. CATALOG_LIMIT
    if query and query ~= "" then url = url .. "&" .. query end
    return url
end

function getCatalogList(index)
    return fetchCatalog(catalogUrl(index + 1))
end

function getCatalogSearch(index, query)
    if index > 0 then return { items = {}, hasNext = false } end
    local r = http_get(API .. "/app/search/releases?query=" .. url_encode(query))
    if not r.success then return { items = {}, hasNext = false } end
    return itemsToResult(json_parse(r.body))
end

function getBookTitle(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d then return nil end
    local t = pickTitle(d.name)
    return t and string_clean(t) or nil
end

function getBookCoverImageUrl(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or type(d.poster) ~= "table" then return nil end
    local src = d.poster.src
    if not src or src == "" then return nil end
    if src:find("^https?://") then return src end
    return baseUrl .. src
end

function getBookDescription(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or not d.description or d.description == "" then return nil end
    return string_trim(d.description)
end

function getBookStatus(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or type(d.is_ongoing) ~= "boolean" then return nil end
    return d.is_ongoing and "Онгоинг" or "Завершён"
end

function getBookRating(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or type(d.rating) ~= "table" then return nil end
    local avg = d.rating.average
    if type(avg) ~= "number" then return nil end
    return "Rating: " .. tostring(avg) .. "/10"
end

function getBookGenres(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or type(d.genres) ~= "table" then return {} end
    local genres = {}
    for _, g in ipairs(d.genres) do
        if g.name and g.name ~= "" then table.insert(genres, g.name) end
    end
    return genres
end

-- Эпизоды = главы, сезон у релиза один — volume не используем.
function getChapterList(bookUrl)
    local d = fetchDetail(bookUrl)
    if not d or type(d.episodes) ~= "table" then return {} end
    local episodes = {}
    for _, ep in ipairs(d.episodes) do table.insert(episodes, ep) end
    table.sort(episodes, function(a, b)
        return (tonumber(a.ordinal) or 0) < (tonumber(b.ordinal) or 0)
    end)
    local chapters = {}
    for _, ep in ipairs(episodes) do
        local ordinal = tonumber(ep.ordinal)
        if ordinal then
            -- Номер серии — обязательный префикс: без него UI показывает
            -- только название, и серии не различаются (пункт "нет номера серии").
            local base = ep.name or ep.name_english
            local title = base and (tostring(ordinal) .. ". " .. base)
                or ("Серия " .. tostring(ordinal))
            table.insert(chapters, {
                title = string_clean(title),
                url   = bookUrl .. "/" .. tostring(ordinal),
            })
        end
    end
    return chapters
end

-- Хэш списка серий для быстрого скипа автообновления: "количество:номер последней".
-- Тот же endpoint, что у getChapterList (detail API), но запрос всегда свежий,
-- без кэша fetchDetail — иначе хэш замёрзнет на время сеанса и движок перестанет
-- замечать новые серии. Ошибка сети или пустой список → nil (полный парс глав).
function getChapterListHash(bookUrl)
    local alias = bookUrl:match("/release/([^/]+)/")
    if not alias then return nil end
    local r = http_get(API .. "/anime/releases/" .. alias)
    if not r.success then return nil end
    local data = json_parse(r.body)
    if type(data) ~= "table" or type(data.episodes) ~= "table" then return nil end
    local count, last = 0, 0
    for _, ep in ipairs(data.episodes) do
        local ordinal = tonumber(ep.ordinal)
        if ordinal then
            count = count + 1
            if ordinal > last then last = ordinal end
        end
    end
    if count == 0 then return nil end
    return count .. ":" .. last
end

-- Потоки эпизода: hls_1080 → hls_720 → hls_480, null-качества пропускаются.
function getVideoList(episodeUrl)
    local alias = episodeUrl:match("/release/([^/]+)/")
    local ordinal = tonumber(episodeUrl:match("/episodes/(%d+)"))
    if not alias or not ordinal then
        error("AniLiberty: не удалось разобрать URL эпизода")
    end
    local r = http_get(API .. "/anime/releases/" .. alias)
    if not r.success then
        error("AniLiberty: API недоступен (HTTP " .. tostring(r.code) .. ")")
    end
    local data = json_parse(r.body)
    if type(data) ~= "table" or type(data.episodes) ~= "table" then
        error("AniLiberty: некорректный ответ API")
    end
    local episode = nil
    for _, ep in ipairs(data.episodes) do
        if tonumber(ep.ordinal) == ordinal then
            episode = ep
            break
        end
    end
    if not episode then return nil end
    local variants = {
        { url = episode.hls_1080, quality = "1080p" },
        { url = episode.hls_720,  quality = "720p" },
        { url = episode.hls_480,  quality = "480p" },
    }
    local sources = {}
    for _, v in ipairs(variants) do
        if type(v.url) == "string" and v.url ~= "" then
            table.insert(sources, { url = v.url, quality = v.quality })
        end
    end
    if #sources == 0 then return nil end
    return sources
end

